package edu.gcu.cst339.lab2_chinook_api.genre;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Data transfer object used as the JSON request and response body for genres.
 *
 * @param genreId the genre ID; generated by the database, so it is ignored on
 *                create and taken from the URL on update
 * @param name    the genre name; required, at most 120 characters
 */
public record GenreDto(
        Integer genreId,
        @NotBlank @Size(max = 120) String name) {

    /**
     * Converts a genre entity into a DTO.
     *
     * @param genre the entity to convert
     * @return a DTO containing the entity's ID and name
     */
    static GenreDto fromEntity(Genre genre) {
        return new GenreDto(genre.getGenreId(), genre.getName());
    }
}